mapper.select:
SELECT so.id, so.code, so.third_code as thirdCode, so.so_id AS soId, so.so_code AS soCode, so.source_code AS sourceCode, so.source_type AS sourceType, so.source_id AS sourceId, so.order_type AS orderType, so.approve_status AS approveStatus, so.warehouse_org_name AS warehouseOrgName, so.carrier_id AS carrierId, so.invalid_status AS invalidStatus, so.plan_delivery_date AS planDeliveryDate, so.actual_delivery_date AS actualDeliveryDate, so.pack_date AS packDate, so.warehouse_id AS warehouseId, so.warehouse_name AS warehouseName, so.approve_user_name AS approveUserName, so.create_user_name AS createUserName, so.create_time AS createTime, so.seller_id AS sellerId, so.seller_name AS sellerName, so.customer_id AS customerId, so.bill_date AS billDate, so.customer_order_no AS customerOrderNo, so.sales_org_id AS salesOrgId, so.sales_org_name AS salesOrgName, so.customer_name AS customerName, so.country AS countryId, sod.id as detailId, so.sales_dept_id AS salesDeptId, sod.id as detailId, sod.sku_id AS skuId, sod.sku_no AS skuNo, sod.plan_qty AS planQty, sod.actual_qty AS actualQty, sod.price, sod.tax_rate as taxRate, sod.amount, sod.currency, sod.currency_symbol as currencySymbol, sod.all_amount_local_currency as allAmountLocalCurrency, sod.exchange_rate as exchangeRate, sod.so_detail_id as soDetailId, sod.source_detail_id AS sourceDetailId, sod.warehouse_location AS warehouseLocation FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE ${params.sqlMap.default} and so.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
so.create_time DESC

SELECT so.id, so.code, so.third_code as thirdCode, so.so_id AS soId, so.so_code AS soCode, so.source_type AS sourceType, so.order_type AS orderType, so.source_id AS sourceId, so.source_code AS sourceCode, so.approve_status AS approveStatus, so.warehouse_org_name AS warehouseOrgName, so.carrier_id AS carrierId, so.invalid_status AS invalidStatus, so.plan_delivery_date AS planDeliveryDate, so.actual_delivery_date AS actualDeliveryDate, so.pack_date AS packDate, so.warehouse_id AS warehouseId, so.warehouse_name AS warehouseName, so.approve_user_name AS approveUserName, so.create_user_name AS createUserName, so.create_time AS createTime, so.track_no AS trackNo, so.seller_id AS sellerId, so.seller_name AS sellerName, so.customer_id AS customerId, so.bill_date AS billDate, so.customer_order_no AS customerOrderNo, so.sales_dept_id AS salesDeptId, so.sales_org_id AS salesOrgId, so.sales_org_name AS salesOrgName, so.customer_name AS customerName, so.country AS countryId, sod.id as detailId, sod.sku_id AS skuId, sod.sku_no AS skuNo, sod.plan_qty AS planQty, sod.actual_qty AS actualQty, sod.price, sod.tax_rate as taxRate, sod.amount, sod.currency, sod.currency_symbol as currencySymbol, sod.all_amount_local_currency as allAmountLocalCurrency, sod.exchange_rate as exchangeRate, sod.so_detail_id as soDetailId, sod.source_detail_id AS sourceDetailId, sod.warehouse_location AS warehouseLocation FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE ${params.sqlMap.default} and so.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
so.create_time DESC

SELECT so.warehouse_id, so.id AS sourceId, so.code AS sourceCode, sod.id AS sourceDetailId, sod.sku_id,sod.sku_no, sod.warehouse_location, sod.actual_qty AS qty, so.bill_date FROM so_outstock so INNER JOIN so_outstock_detail sod ON sod.main_id=so.id AND sod.is_deleted=FALSE WHERE so.is_deleted=FALSE
AND so.id IN
#{id}

SELECT approve_status, invalid_status, count(*) FROM so_outstock WHERE is_deleted=FALSE
${permissionSql}
GROUP BY approve_status,invalid_status

SELECT DISTINCT so.id, so.code, so.source_type, so.seller_name, so.warehouse_name, so.approve_status, so.create_time FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE so.is_deleted = false AND so.invalid_status = false AND so.source_type NOT IN ('SAL_OUTSTOCK')
and so.approve_status in
#{item}
AND so.actual_delivery_date >= #{params.actualDeliveryDateList[0]} and (#{params.actualDeliveryDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.actual_delivery_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY so.create_time desc

select count(distinct so.id) FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE AND so.source_type NOT IN ('SAL_OUTSTOCK')
and so.approve_status in
#{item}
AND so.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.bill_date
and so.invalid_status = #{params.invalidStatus}
${params.permissionSql}

mapper.sql:
WHERE T.approve_status = 'approve' AND T.is_deleted = 'f' and G.is_deleted = 'f'
and g.id > #{params.id}
AND t.customer_name IN
#{name}
AND t.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > t.bill_date
AND t.warehouse_name = #{params.warehouseName}
and not exists (select id from wms_data_compare_temp where system_data_id = g.id and task_id = #{params.taskId})
